  function toFighter(ent, gridSize, teamId) {
    return {
      id: ent.id || ent.name,
      ent,
      cellId: cellIdOf(ent.c, ent.r, gridSize),
      hp: ent.pv,
      maxHp: ent.pvMax,
      shield: ent.shield | 0,
      hidden: (ent.invis | 0) > 0,
      ap: ent.pa,
      mp: ent.pm,
      level: ent.level || 1,
      teamId: teamId,
      stats: Object.assign({}, ent.stats, { agility: ent.stats && ent.stats.agi })
    };
  }

